  "a_sentences": [
    {
      "a_text": "P1 Streitig ist, ob die Vorinstanz Bundesrecht verletzte, indem sie wegen Fristversäumnisses aufgrund falscher elektronischer Versandart auf die Beschwerde nicht eintrat.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Nach Art. 60 Abs. 1 ATSG ist die Beschwerde innerhalb von 30 Tagen nach Eröffnung des Einspracheentscheids einzureichen.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 Die Frist ist nur gewahrt, wenn die Beschwerde spätestens am letzten Tag der Frist beim Gericht eingereicht oder der Post übergeben wird.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Die strikte Anwendung der Fristbestimmungen stellt grundsätzlich keinen überspitzten Formalismus dar.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Für die Fristwahrung bei elektronischer Übermittlung ist seit 1. Januar 2017 der Zeitpunkt massgebend, in dem die Zustellplattform die Abgabequittung ausstellt.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Eine Abgabequittung belegt, dass alle auf Seiten der Partei für die Übermittlung notwendigen Schritte abgeschlossen sind.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Die Versicherte vermag nicht aufzuzeigen, dass die Vorinstanz kantonales Recht willkürlich anwandte, indem sie die Eingabe mangels Abgabequittung als ungültig qualifizierte.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Fehlt die Abgabequittung, muss die Partei die Eingabe nochmals zustellen, allenfalls auf dem postalischen Weg.",
      "b_propositions": ["P8"]
    }
  ]
}
